import React from "react";
import { createLazyLitComponent, litReactModule } from "./lazy-lit.js";

/**
 * Browser-only React wrapper for `<jz-tab-item>`.
 * Lit is imported after mount so Node / Next SSR never evaluates lit-html.
 */
export const JzTabItem = createLazyLitComponent(async () => {
  const [{ createComponent }, { JzTabItemElement }] = await Promise.all([
    import("@lit/react"),
    import("../designSystem/components/jz-tab-item/jz-tab-item.js"),
  ]);
  return createComponent({
    tagName: "jz-tab-item",
    elementClass: JzTabItemElement,
    react: litReactModule(React),
    events: {
      onClick: "click",
    },
  }) as React.ComponentType<Record<string, unknown>>;
}, "JzTabItem");
